// The native inventory confirms selection and drawing. The VR task then owns
// the same sword until it is returned or its original owner is replaced.
// The visible sheath, draw gesture and return task share this anatomical frame.
// HMD look orientation does not enter the storage calculation.
const swordHolster=(()=>{
 const m=bodyInteraction.math;
 const requested=()=>'HIP';   // the sword lives on the hip; Altair's Short Blade lives on the back (see nativeHeldSword)
 const range=()=>{try{return connectedSettings.values.swordGrabReach||.34;}catch(_){return .34;}};
 function anchor(body,mode){
  const a=bodyInteraction.anatomy(body);if(!a)return null;
  if(mode==='HIP')return {...a.sword,mode:'HIP',source:a.source};
  const q=body.torsoQ||body.q,shoulder=body.shoulders?.[1];if(!shoulder)return null;
  // Mouth just above/behind the right shoulder; blade runs diagonally down
  // the back toward the left waist. Mesh local -Z is the blade direction.
  const position=m.add(shoulder,m.rotate(q,[.025,-.14,.17])),angle=22*Math.PI/180;
  return {position,quaternion:m.mul(q,[0,Math.sin(angle/2),0,Math.cos(angle/2)]),
   radius:.34,selection:2,mode:'BACK',torsoQ:q.slice(),shoulder:shoulder.slice(),source:'ACCEPTED_BODY_RIGHT_SHOULDER'};
 }
 function near(hand,hilt,home,stowing){
  // Putting a blade back is more forgiving than drawing one: the hand is already holding it,
  // so a wrong accept cannot start an unwanted draw.
  if(!home||m.len(m.sub(hilt.position,home.position))>(stowing?range()+.12:range()))return false;
  // The same spherical zone must not draw a sword from in front of the chest.
  if(home.mode==='BACK'){
   const p=m.rotate(m.inv(home.torsoQ),m.sub(hilt.position,home.shoulder));
   if(stowing){if(p[1]>.18||p[0]<-.22||p[2]<-.28)return false;}
   else if(p[1]>.08||p[0]<-.12||p[2]<-.15)return false;
  }
  return true;
 }
 return {requested,anchor,near,range};
})();

// One inventory-confirmed sword task, including its visible world pose.
// No native weapon-state, health, actor transform or animation timer writes.
// The game owns slot 3, the EntityRef and the detached Havok body.
const nativeSwordInventory = (() => {
  const slot = 3;
  const table = ptr('0x17230f0');
  const abi = {abi:'thiscall', scheduling:'cooperative', exceptions:'steal', traps:'none'};
  const pins = {
    read: ['0xce70c0', '8b8104ffffff8b5050'],
    drop: ['0xce4b80', '8b8104ffffff8b542404'],
    pickup: ['0xce9b20', '6aff68d0ce570164'],
    retain: ['0x47f300', '568bf18b4c240885c9'],
    release: ['0x474900', '518b018d480483caff'],
  };
  const original = (name, result, args) => new NativeFunction(ptr(pins[name][0]), result, args, abi);
  const readSlot = original('read', 'pointer', ['pointer', 'uint']);
  const dropSlot = original('drop', 'void', ['pointer', 'uint']);
  const pickupSlot = original('pickup', 'uint8', ['pointer', 'pointer', 'uint', 'uint8']);
  const retain = original('retain', 'pointer', ['pointer', 'pointer']);
  const release = original('release', 'void', ['pointer']);
  let verified = false;

  function verify() {
    if (verified) return;
    if (table.add(0xbc).readU32() !== 0xce70c0 || table.add(0xc0).readU32() !== 0xce4b80 ||
        table.add(0xb4).readU32() !== 0xce9b20 ||
        Object.values(pins).some(([address, bytes]) => hx(ptr(address), bytes.length/2) !== bytes))
      throw Error('Original sword inventory methods differ');
    verified = true;
  }

  function binding(o) {
    verify();
    const human = ptr(o.human), inventory = human.add(0xfc);
    if (human.readU32() !== 0x1723250 || human.add(0x104).readPointer().toString() !== o.entity ||
        !inventory.readPointer().equals(table) || human.add(0xf8).readU8() === 0)
      throw Error('Original Human sword inventory changed');
    return inventory;
  }

  function itemAt(inventory, index) {
    const address = readSlot(inventory, index);
    const ref = address.isNull() ? NULL : address.readPointer();
    if (ref.isNull() || !(ref.add(8).readU32() & 0x10000000)) return null;
    return describe(ref.readPointer(), ref, index);
  }

  function describe(item, ref=item.add(0xd0).readPointer(), index=slot) {
    if (item.isNull() || ref.isNull() || nativeType(item).name !== 'Entity') return null;
    const count = item.add(0x78).readU32() & 0x3fff, list = item.add(0x74).readPointer();
    if (count > 64 || (count && list.isNull())) throw Error('Unexpected weapon component table');
    const components = [];
    for (let index=0; index<count; index++) {
      const component = list.add(4*index).readPointer();
      if (!component.isNull() && component.add(8).readPointer().equals(item))
        components.push({pointer:component.toString(), type:nativeType(component)});
    }
    return {slot:index, entity:item.toString(), reference:ref.toString(), components};
  }

  const sameItem = (a, b) => !!a && !!b && a.entity === b.entity && a.reference === b.reference;
  function sword(o) {
    const item = itemAt(binding(o), slot);
    if (item && !item.components.some(part => part.type.typeId === 0x45866243))
      throw Error('Something other than a weapon occupies the original sword slot');
    return item;
  }

  function snapshot(human, entity) {
    const inventory = binding({human:human.toString(), entity:entity.toString()});
    const items = Array.from({length:16}, (_,index)=>itemAt(inventory,index)).filter(Boolean);
    return {owner:entity.toString(), interface:inventory.toString(), items};
  }

  function body(item) {
    const entity = ptr(item.entity), reference = ptr(item.reference);
    if (!(reference.add(8).readU32() & 0x10000000) || !reference.readPointer().equals(entity) ||
        !entity.add(0xd0).readPointer().equals(reference) || nativeType(entity).name !== 'Entity')
      return null;
    const position = floats(fpRootPointer(item.entity).add(0x30), 3);
    if (!position.every(Number.isFinite)) return null;
    const part = item.components.find(component=>component.type.name === 'RigidBodyComponent');
    const component = ptr(part?.pointer || 0);
    if (component.isNull() || !component.add(8).readPointer().equals(entity) ||
        nativeType(component).name !== 'RigidBodyComponent') return null;
    const originalBody = component.add(0x80), havok = originalBody.add(0x74).readPointer();
    return {entity:item.entity, reference:item.reference, body:originalBody.toString(), position,
      havok:havok.toString(), physicsWorld:havok.isNull() ? null : havok.add(8).readPointer().toString(),
      motionType:havok.isNull() ? null : havok.add(0xa8).readU8(),
      velocity:havok.isNull() ? null : floats(havok.add(0x180), 3)};
  }

  function freed(o, item) {
    dropSlot(binding(o), slot);
    if (sword(o)) throw Error('Original sword slot did not clear');
    const detached = body(item);
    if (!detached || detached.physicsWorld !== o.world || detached.motionType !== 2)
      throw Error('Original sword did not register its detached body in Havok');
    return detached;
  }

  function apply({player, guard, wanted, action}) {
    const current = sword(player);
    const guarded = guard ? sword(guard) : null;
    const result = {action, frame, thread:Process.getCurrentThreadId(), before:{player:current, guard:guarded},
      restoration:[]};
    const refs = [];
    const keep = item => {
      if (!item) return;
      const block = Memory.alloc(4);
      retain(block, ptr(item.entity));
      refs.push(block);
      if (block.readPointer().toString() !== item.reference) throw Error('Retained sword reference changed');
    };
    const assign = (owner,item) => {
      const accepted = !!pickupSlot(binding(owner), ptr(item.entity), slot, 1);
      if (!accepted || !sameItem(sword(owner), item)) throw Error('Original inventory rejected the sword');
    };
    try {
      if (action === 'DROP' ? !sameItem(current,wanted) : (
          sameItem(current,wanted) || (guard ? !sameItem(guarded,wanted) :
            body(wanted)?.physicsWorld !== player.world)))
        throw Error('Sword ownership changed before the input reached the world');
      keep(current);
      if (action === 'PICKUP') keep(wanted);
      if (guard) result.guardDrop = freed(guard,wanted);
      if (current) result.playerDrop = freed(player,current);
      if (action === 'PICKUP') assign(player,wanted);
      result.pickupAccepted = action === 'PICKUP';
      result.phase = action === 'DROP' ? 'DROPPED' : 'TRANSFERRED';
    } catch (error) {
      result.phase = 'REFUSED';
      result.error = String(error);
      // Restore only cleared slots belonging to this operation and still holding their own references.
      try {
        if (guard && !sword(guard) && sameItem(sword(player),guarded)) {
          dropSlot(binding(player),slot);
          result.restoration.push({owner:player.entity, removedPartialPickup:!sword(player)});
        }
      } catch (partialError) {
        result.restoration.push({owner:player.entity,error:String(partialError)});
      }
      for (const [owner,item] of [[player,current],[guard,guarded]]) {
        if (!owner || !item || !refs.some(block=>block.readPointer().toString()===item.reference)) continue;
        try {
          if (!sword(owner) && !sameItem(sword(player),item) && !(guard && sameItem(sword(guard),item))) {
            assign(owner,item);
            result.restoration.push({owner:owner.entity,restored:true});
          }
        } catch (restoreError) {
          result.restoration.push({owner:owner.entity,error:String(restoreError)});
        }
      }
    } finally {
      for (const block of refs) {
        if (!block.readPointer().isNull()) release(block);
      }
    }
    result.after = {guard:guard ? sword(guard) : null, player:sword(player)};
    return result;
  }

  return {sword, snapshot, body, sameItem, apply, describe};
})();

// An accepted right-hand grip proposes a pickup. The original world update owns the commit.
// Original Entity and Havok ownership stays with the active game's World.
const SWORD_RACK_REMOVED = true;   // sword rack and the generated custom swords removed at the user's request (frame rate). Set to false to bring them back.
const swordRack = (() => {
  const math = bodyInteraction.math;
  const options = {abi:'thiscall', scheduling:'cooperative', exceptions:'steal', traps:'none'};
  const api = {...npcSwordLab.factory};
  const methods = {
    worldOf:['0x47df20','8b416c85c074048b4010c333','pointer',['pointer']],
    lock:['0x418100','53568bf1ff15fc0b9d028bd8','void',['pointer']],
    unlock:['0x416c30','568bf18b0650ff15400c9d02','void',['pointer']],
    addBody:['0x55e9f0','53568bf18d9e800000008bcb','void',['pointer','uint8']],
    remove:['0x4944a0','8b4424045051e875ba020083','void',['pointer','pointer']],
  };
  const count = 5, spacing = .34, hiltHeight = 1.12;
  const poseStorage = Memory.alloc(32);
  const pose = ptr((poseStorage.toUInt32()+15)&0xfffffff0);
  const output = Memory.alloc(4);
  const items = [];
  let view = null;
  let lastPlacementSearch = null;
  let state = {phase:'WAITING'};

  function bind() {
    if (api.worldOf) return;
    for (const [address,bytes] of Object.values(methods)) {
      if (hx(ptr(address),bytes.length/2) !== bytes) throw Error('Original rack method differs at '+address);
    }
    for (const [name,[address,,result,args]] of Object.entries(methods)) {
      api[name] = new NativeFunction(ptr(address),result,args,options);
    }
  }

  function vector(values) {
    values.forEach((component,index)=>pose.add(index*4).writeFloat(component));
  }

  function place(entity, position, rotation) {
    vector(rotation);
    api.rotate(entity,pose);
    vector([...position,1]);
    api.position(entity,pose);
  }

  function arrangement(root, nav, scene) {
    const f = math.rotate(nav,[0,1,0]);
    const yaw = Math.atan2(-f[0],f[1]);
    const facing = [0,0,Math.sin(yaw/2),Math.cos(yaw/2)];
    const rotation = math.mul(facing,[Math.SQRT1_2,Math.SQRT1_2,0,0]);
    for (const [side,ahead] of [[0,.87],[.34,.87],[-.34,.87],[0,1.16],[0,-.94]]) {
      const middle = math.add(root,math.rotate(facing,[side,ahead,0]));
      const ground = [];
      for (let i=0;i<count;i++) {
        const point = math.add(middle,math.rotate(facing,[(i-2)*spacing,0,0]));
        const start = [point[0],point[1],root[2]+.70];
        const end = [point[0],point[1],root[2]-.40];
        const hit = solidShapes.move(scene.tree,start,end,.035);
        if (!hit.blocked || hit.unresolved || !hit.contacts.some(c=>c.normal[2]>.72)) break;
        ground.push({position:[point[0],point[1],hit.position[2]-.035]});
      }
      if (ground.length!==count) continue;
      const levels = ground.map(row=>row.position[2]);
      if (Math.max(...levels)-Math.min(...levels)>.17) continue;
      const base = Math.max(...levels);
      const positions = ground.map(row=>[row.position[0],row.position[1],base+hiltHeight]);
      const clear = positions.every(end=> {
        const from = [root[0],root[1],end[2]];
        const across = solidShapes.move(scene.tree,from,end,.055);
        const down = solidShapes.move(scene.tree,end,[end[0],end[1],base+.16],.076);
        return !across.blocked && !across.unresolved && !down.blocked && !down.unresolved;
      });
      if (clear) return {positions, rotation, center:[middle[0],middle[1],base], facing};
    }
    return null;
  }

  function create(player, root, own) {
    const locomotion = fpView.last?.bodyFrame;
    const scene = solidWorld.current;
    if (!own || !scene?.tree.count || !locomotion || stereo.pair ||
        checkpointBoot.state!=='SUBMITTED' || locomotion.mode!=='NATIVE_GROUND_POSITION') return;
    const tick = GetTickCount();
    if (lastPlacementSearch?.world===player.world && ((tick-lastPlacementSearch.tick)>>>0)<650 &&
        math.len(math.sub(root,lastPlacementSearch.root))<.30) return;
    lastPlacementSearch = {world:player.world,root:root.slice(),tick};
    const placement = arrangement(root,locomotion.navigationQ || locomotion.q,scene);
    if (!placement) return;
    bind();
    const world = api.worldOf(ptr(player.entity));
    if (world.isNull() || nativeType(world).name !== 'World' ||
        !world.add(0x90).readPointer().add(0x18).readPointer().equals(ptr(player.world)))
      throw Error('The original player is outside the current world');
    const from = ptr(own.entity), sourceWorld = api.worldOf(from);
    if (!sourceWorld.isNull() && !sourceWorld.equals(world)) throw Error('Source sword belongs to another world');

    state = {phase:'SPAWNING', world:player.world, gameWorld:world.toString(), player:player.entity,
      source:own.entity, sourceReference:own.reference, center:placement.center, facing:placement.facing,
      spacing, started:frame, tick:GetTickCount()};
    placement.positions.forEach((position,index)=>{
      output.writePointer(NULL);
      api.clone(from,output);
      const entity = output.readPointer();
      if (entity.isNull() || entity.equals(from) || nativeType(entity).name !== 'Entity')
        throw Error('Original factory returned no separate sword');
      const before = nativeSwordInventory.describe(entity);
      if (!before || !before.components.some(component=>component.type.name==='BhvWeapon') ||
          before.components.some(component=>own.components.some(original=>original.pointer===component.pointer)))
        throw Error('Cloned sword components are not independently owned');
      const row = {entity:entity.toString(), variant:index+1, position, beforeReference:before.reference,
        item:null, activation:null, mounted:null};
      items.push(row);
      place(entity,position,placement.rotation);
      api.add(world,entity);
      row.queued = true;
    });
    tell('native_sword_rack',{...state,entities:items.map(row=>row.entity)});
  }

  function addMountedBody(item, world) {
    const part = item.components.find(component=>component.type.name==='RigidBodyComponent');
    const component = ptr(part?.pointer || 0);
    if (component.isNull() || component.readU32()!==0x1693040 ||
        !component.add(8).readPointer().equals(ptr(item.entity)))
      throw Error('Original sword clone has no independent RigidBodyComponent');
    const lock = world.add(0x90).readPointer().add(0x828);
    // The inventory release at 0xce9e08 enables this same component before adding it.
    api.lock(lock);
    try {
      const oldEnabled = component.add(0x103).readU8();
      component.add(0x103).writeU8(1);
      api.addBody(component,1);
      return {frame,oldEnabled};
    } finally {
      api.unlock(lock);
    }
  }

  function admission(world) {
    let ready = true;
    for (const row of items) {
      if (row.mounted) continue;
      const entity = ptr(row.entity);
      const registeredWorld = api.worldOf(entity).toString();
      if (registeredWorld!==state.gameWorld) {
        ready = false;
        continue;
      }
      const item = nativeSwordInventory.describe(entity);
      const body = item && nativeSwordInventory.body(item);
      row.lastBody = body;
      if (body?.physicsWorld==='0x0' && !row.activation) row.activation=addMountedBody(item,world);
      if (body?.physicsWorld===state.world && body.motionType===6 &&
          math.len(math.sub(body.position,row.position))<.05) {
        row.mounted = {frame,body};
        row.item = item;
      } else ready = false;
    }
    return ready;
  }

  function buildView(player, root, own) {
    let held = 0;
    const rows = [];
    for (const entry of items) {
      if (nativeSwordInventory.sameItem(entry.item,own)) {
        held = entry.variant;
        continue;
      }
      let body;
      try { body = nativeSwordInventory.body(entry.item); } catch (_) { continue; }
      if (body?.physicsWorld!==player.world || math.len(math.sub(root,body.position))>8) continue;
      const entity = ptr(body.entity);
      const matrix = floats(fpRootPointer(body.entity),16);
      if (!matrix.every(Number.isFinite)) continue;
      rows.push({entity:body.entity, reference:entry.item.reference, variant:entry.variant,
        position:body.position, body:body.body, havok:body.havok, motionType:body.motionType, matrix,
        render:entity.add(0xac).readPointer().toString()});
    }
    const nearby = math.len(math.sub(root,state.center)) < 12;
    view = {player:player.entity, generation:player.generation, held, rows, rack:nearby,
      center:state.center, facing:state.facing, frame, tick:GetTickCount()};
  }

  function step(player, root, own) {
    if (SWORD_RACK_REMOVED) return [];
    if (state.world && (state.world!==player.world || state.player!==player.entity)) {
      items.length=0;
      state={phase:'WAITING'};
      view=null;
      lastPlacementSearch=null;
    }
    if (state.phase==='FAILED') return [];
    try {
      if (state.phase==='WAITING') {
        create(player,root,own);
      } else if (state.phase==='SPAWNING') {
        if (admission(ptr(state.gameWorld))) {
          state.phase='READY';
          state.ready=frame;
          buildView(player,root,own);
          tell('native_sword_rack',{...state,items:items.map(item=>({variant:item.variant,mounted:item.mounted}))});
          return items.map(row=>row.item);
        }
        if (((GetTickCount()-state.tick)>>>0)>2500) throw Error('Original world did not mount every sword');
      } else buildView(player,root,own);
    } catch (error) {
      if (state.phase==='SPAWNING') {
        for (const row of items) if (row.queued) {
          try { api.remove(ptr(state.gameWorld),ptr(row.entity)); } catch (_) {}
        }
      }
      state.phase='FAILED';
      state.error=String(error);
      view=null;
      tell('native_sword_rack',state);
    }
    return [];
  }

  function isMounted(item) {
    return state.phase==='READY' && items.some(row=>nativeSwordInventory.sameItem(row.item,item));
  }

  function scene() {
    if (SWORD_RACK_REMOVED) return null;
    return view?.player===fpView.actor?.entity && view.generation===fpView.seed?.generation &&
      ((GetTickCount()-view.tick)>>>0)<250 ? view : null;
  }

  rpc.exports.swordRack = () => ({...state,items:items.slice(),visual:scene()});
  return {step,isMounted,scene};
})();

const armoryRender = (() => {
  const memory = Memory.alloc(480);
  let last = null;
  function snapshot(pair) {
    if (pair.armory !== undefined) return pair.armory;
    pair.armory = vrMode.current==='FIRST_PERSON' && fpView.prepared && !pair.headOnly ? swordRack.scene() : null;
    return pair.armory;
  }

  function submit(pair) {
    let scene = snapshot(pair);
    // F8 > Mods: a chosen custom sword is drawn in the hand and on the belt; Altair's Short Blade is always drawn from the back sheath.
    if (!scene) {
      let pick = 0;
      try { pick = connectedSettings.values.modWeapon|0; } catch (_) {}
      if (pick < 0 || pick > 5) pick = 0;
      if (vrMode.current!=='FIRST_PERSON' || !fpView.prepared || pair.headOnly) return;
      const sh = (globalThis.__ac1UiV2&&globalThis.__ac1UiV2()) ? nativeHeldSword.sheaths() : null;
      const rows = [];
      if (sh && sh.back) {
        const r = bodyInteraction.math.rotate, q = sh.back.quaternion;
        rows.push({variant:7, matrix:[...r(q,[1,0,0]),0,...r(q,[0,1,0]),0,...r(q,[0,0,1]),0,...sh.back.position,1]});
      }
      const held = (pick ? pick+1 : 0) + (sh && sh.bladeInHand ? 16 : 0);
      if (!held && !rows.length) return;
      scene = {rows, held, rack:false, facing:[0,0,0,1], center:[0,0,0]};
    }
    const glow = 1; // Sword of Eden: heartbeat glow is always on when it is the held sword
    const fields = [scene.rows.length,scene.held,Number(scene.rack),glow];
    fields.forEach((v,i)=>memory.add(4*i).writeU32(v));
    const axis = bodyInteraction.math.rotate;
    const matrix = [[1,0,0],[0,1,0],[0,0,1]].flatMap(v=>[...axis(scene.facing,v),0]);
    [...matrix,...scene.center,1].forEach((v,i)=>memory.add(16+4*i).writeFloat(v));
    scene.rows.forEach((row,i)=>{
      const start = memory.add(80+80*i);
      start.writeU32(row.variant);
      row.matrix.forEach((v,j)=>start.add(16+4*j).writeFloat(v));
    });
    const result = daAPI.armory(memory,pair.id);
    last = {pair:pair.id, frame:pair.frame, held:scene.held, rack:scene.rack,
      variants:scene.rows.map(row=>row.variant), result};
  }
  rpc.exports.armoryRender = () => last;
  return {snapshot,submit};
})();

// Shape of a closed fist around a hilt: thumb, index, middle, ring, little. Scaled by the menu's Sword grip wrap.
const BLADE_GRIP_SHAPE=[.70,1,1,1,.98];
const SWORD_HELD_UP=[Math.sin(32.5*Math.PI/180),0,0,Math.cos(32.5*Math.PI/180)];   // blade out of the top of the fist, leaning 25 degrees forward
// Tunable grip: the menu's Blade tab can rotate and slide the blade inside the fist while we find the
// numbers that look right. Defaults reproduce SWORD_HELD_UP exactly, so an untouched menu changes nothing.
function heldBladeAdjust(){
 let tilt=83,yaw=-10,roll=5,along=.015;
 try{const v=connectedSettings.values;
  if(typeof v.gripTilt==='number')tilt=v.gripTilt;
  if(typeof v.gripYaw==='number')yaw=v.gripYaw;
  if(typeof v.gripRoll==='number')roll=v.gripRoll;
  if(typeof v.gripAlong==='number')along=v.gripAlong;}catch(_){}
 const R=Math.PI/180,ax=(a,d)=>{const h=d*R/2,c=Math.cos(h),sn=Math.sin(h);return a===0?[sn,0,0,c]:a===1?[0,sn,0,c]:[0,0,sn,c];};
 const mul=(a,b)=>[a[3]*b[0]+a[0]*b[3]+a[1]*b[2]-a[2]*b[1],a[3]*b[1]-a[0]*b[2]+a[1]*b[3]+a[2]*b[0],
  a[3]*b[2]+a[0]*b[1]-a[1]*b[0]+a[2]*b[3],a[3]*b[3]-a[0]*b[0]-a[1]*b[1]-a[2]*b[2]];
 return {q:mul(mul(ax(0,tilt),ax(1,yaw)),ax(2,roll)),along};
}
