 function adjust(s,authored){
  if(s.mode==='weather')return weatherLight(s,authored);
  if(s.mode==='native')return {altitude:authored[1],gain:1,ambient:1,properties:authored,
   light:[1,1,1],sky:[1,1,1]};
  const [azimuth,elevation,intensity,fill,fillAzimuth,fillElevation]=authored;
  const arc=s.mode==='hold'?0:360*s.elapsed/s.seconds;
  // Start at the authored position. Advance continuously through sunset,
  // midnight and the opposite horizon without flipping the light's azimuth.
  const amplitude=Math.sin(Math.min(89.5,Math.max(65,Math.abs(elevation)))*rad);
  const origin=Math.asin(Math.max(-1,Math.min(1,Math.sin(elevation*rad)/amplitude)));
  const altitude=s.mode==='hold'?elevation+s.degrees:
   Math.asin(amplitude*Math.sin(origin-arc*rad))/rad;
  const azimuthAdvance=s.mode==='hold'?0:arc;
  const gain=s.mode==='hold'?s.gain:smooth(altitude/Math.min(16,Math.max(3,elevation)));
  const ambient=s.mode==='hold'?(s.ambient??(.20+.80*s.gain)):.20+.80*smooth((altitude+10)/28);
  const daylight=smooth((altitude+12)/30);
  const warm=s.chroma===false?0:smooth((altitude+10)/12)*(1-smooth((altitude-4)/21));
  const light=[1,1-.17*warm,1-.37*warm];
  const sky=[.06,.10,.21].map((night,i)=>(night+(1-night)*daylight)*light[i]);
  // Original shadow-volume bounds divide by the ray's vertical component.
  const safeElevation=Math.max(3,Math.min(89.5,altitude));
  return {altitude,gain,ambient,light,sky,properties:[wrap(azimuth+azimuthAdvance),
   safeElevation,intensity*gain,fill*gain,wrap(fillAzimuth+azimuthAdvance),
   Math.max(3,Math.min(89.5,safeElevation+fillElevation-elevation))]};
 }

